// Kept in sync with the design system's side-panel.component.scss.
@use '@acme/design-system/theme/spacing' as *;

$panel-width: 420px;
$panel-trigger-top: $space-21;
$panel-trigger-half-width: $space-9;
$panel-animation-duration: 0.3s;
$panel-z-index: 1041;

.panel-trigger-container {
  height: 0;
  pointer-events: none;
}

.panel-trigger {
  position: fixed;
  top: $panel-trigger-top;
  right: 0;
  z-index: $panel-z-index;
  pointer-events: auto;
  transition: right $panel-animation-duration ease-in-out;

  &.open {
    right: $panel-width;
  }
}

.panel {
  position: fixed;
  top: 0;
  right: 0;
  width: $panel-width;
  height: 100vh;
  z-index: $panel-z-index;
  transform: translateX(100%);
  transition: transform $panel-animation-duration ease-in-out;

  &.open {
    transform: translateX(0);
  }
}
